            final int stride=28;vertices.position(0);GLES20.glEnableVertexAttribArray(aPos);GLES20.glVertexAttribPointer(aPos,3,GLES20.GL_FLOAT,false,stride,vertices);vertices.position(3);GLES20.glEnableVertexAttribArray(aNormal);GLES20.glVertexAttribPointer(aNormal,3,GLES20.GL_FLOAT,false,stride,vertices);vertices.position(6);GLES20.glEnableVertexAttribArray(aPart);GLES20.glVertexAttribPointer(aPart,1,GLES20.GL_FLOAT,false,stride,vertices);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,vertexCount);GLES20.glDisableVertexAttribArray(aPos);GLES20.glDisableVertexAttribArray(aNormal);GLES20.glDisableVertexAttribArray(aPart);
